-- =====================================================================
-- Séances express de départ : une bibliothèque variée, écrite dans l'esprit
-- des programmes et de la fiche « Séances courtes de secours » de la coach
-- (gros mouvements, RPE 7-9, circuits abdos et cardio, marche).
-- Toutes en BROUILLON : la coach les relit, les modifie, puis les publie.
-- Une séance déjà présente (même titre) n'est pas recréée.
-- =====================================================================

insert into public.seances_express (titre, description, duree_minutes, materiel, type, niveau, contenu, publiee, visibilite)
select v.titre, v.description, v.duree_minutes, v.materiel, v.type, v.niveau, v.contenu, false, 'toutes'
from (values
  ('Réveil articulaire', '5 minutes pour dérouiller tout le corps, au réveil ou après une longue journée assise.', 5, '{}'::text[], 'Mobilité', 'tous', $seance${"nom": "Réveil articulaire", "jour": null, "duree": "5 min", "echauffement": null, "blocs": [{"titre": "Mobilité", "format": "2 tours", "exercices": [{"nom": "Cercles de chevilles et de genoux", "series": null, "repetitions": "30 s", "charge": null, "repos": null, "tempo": null, "consignes": "Lentement, dans les deux sens."}, {"nom": "Cercles de hanches", "series": null, "repetitions": "30 s", "charge": null, "repos": null, "tempo": null, "consignes": "Mains sur les hanches, grands cercles amples."}, {"nom": "Rotations du buste", "series": null, "repetitions": "30 s", "charge": null, "repos": null, "tempo": null, "consignes": "Bassin fixe, tu tournes seulement le haut du corps."}, {"nom": "Cercles de bras", "series": null, "repetitions": "30 s", "charge": null, "repos": null, "tempo": null, "consignes": "Petits cercles puis grands, vers l’avant puis vers l’arrière."}, {"nom": "Squat lent au poids du corps", "series": null, "repetitions": "30 s", "charge": null, "repos": null, "tempo": null, "consignes": "Descends doucement, talons au sol, poitrine haute."}]}], "retour_au_calme": "Trois grandes respirations, épaules relâchées.", "notes": "Idéal aussi juste avant une séance plus longue."}$seance$::jsonb),
  ('Tabata gainage', '4 minutes intenses pour ta sangle abdominale, juste avec un tapis.', 5, array['Tapis']::text[], 'Gainage', 'intermediaire', $seance${"nom": "Tabata gainage", "jour": null, "duree": "5 min", "echauffement": "1 min : chat-vache à quatre pattes puis 20 s de planche facile sur les genoux.", "blocs": [{"titre": "Tabata", "format": "Tabata", "exercices": [{"nom": "Planche sur les coudes", "series": null, "repetitions": "20 s", "charge": null, "repos": null, "tempo": null, "consignes": "Bassin dans l’alignement, tu serres les fessiers et le ventre."}, {"nom": "Mountain climbers lents", "series": null, "repetitions": "20 s", "charge": null, "repos": null, "tempo": null, "consignes": "Genou vers la poitrine, sans faire monter les fesses."}, {"nom": "Dead bug", "series": null, "repetitions": "20 s", "charge": null, "repos": null, "tempo": null, "consignes": "Bas du dos collé au sol, tu expires quand le bras et la jambe s’allongent."}, {"nom": "Gainage latéral", "series": null, "repetitions": "20 s", "charge": null, "repos": null, "tempo": null, "consignes": "Alterne le côté à chaque tour. Sur les genoux si besoin."}]}], "retour_au_calme": null, "notes": "20 s d’effort, 10 s de repos, 8 tours : l’appli te guide. Tu alternes les 4 exercices dans l’ordre."}$seance$::jsonb),
  ('Cardio 30/30 au salon', '10 minutes pour faire monter le cœur, sans matériel et sans sauter si tu préfères.', 10, '{}'::text[], 'Cardio', 'tous', $seance${"nom": "Cardio 30/30 au salon", "jour": null, "duree": "10 min", "echauffement": "1 min de marche rapide sur place en balançant les bras.", "blocs": [{"titre": "Circuit 30/30", "format": "2 tours – repos 1 min entre les tours", "exercices": [{"nom": "Montées de genoux", "series": null, "repetitions": "30 s", "charge": null, "repos": "30 s", "tempo": null, "consignes": "Version douce : genoux à hauteur de hanche, en marchant vite."}, {"nom": "Squat au poids du corps", "series": null, "repetitions": "30 s", "charge": null, "repos": "30 s", "tempo": null, "consignes": "Talons au sol, tu pousses le sol pour remonter."}, {"nom": "Mountain climbers", "series": null, "repetitions": "30 s", "charge": null, "repos": "30 s", "tempo": null, "consignes": "Mains sous les épaules, rythme régulier."}, {"nom": "Fentes arrière alternées", "series": null, "repetitions": "30 s", "charge": null, "repos": "30 s", "tempo": null, "consignes": "Genou arrière qui frôle le sol, buste droit."}]}], "retour_au_calme": "1 min de marche lente, puis étire tes mollets et tes cuisses.", "notes": "30 s d’effort, 30 s de repos. Va à ton rythme : l’important, c’est de bouger."}$seance$::jsonb),
  ('Sangle abdominale', '10 minutes de gainage intelligent, sans crunch, pour un ventre solide.', 10, array['Tapis']::text[], 'Gainage', 'tous', $seance${"nom": "Sangle abdominale", "jour": null, "duree": "10 min", "echauffement": "1 min : respiration ventrale allongée, puis 10 bascules du bassin.", "blocs": [{"titre": "Circuit abdos", "format": "3 tours – repos 1 min entre les tours", "exercices": [{"nom": "Dead bug", "series": null, "repetitions": "40 s", "charge": null, "repos": "20 s", "tempo": null, "consignes": "Bas du dos collé au sol, mouvement lent et contrôlé."}, {"nom": "Planche sur les coudes", "series": null, "repetitions": "40 s", "charge": null, "repos": "20 s", "tempo": null, "consignes": "Corps bien aligné, tu respires calmement."}, {"nom": "Gainage latéral", "series": null, "repetitions": "20 s / côté", "charge": null, "repos": "20 s", "tempo": null, "consignes": "Hanches hautes. Sur les genoux pour la version plus facile."}, {"nom": "Bird dog", "series": null, "repetitions": "40 s", "charge": null, "repos": null, "tempo": null, "consignes": "À quatre pattes : bras et jambe opposés, sans bouger le bassin."}]}], "retour_au_calme": "Posture de l’enfant 1 min, en respirant dans le dos.", "notes": null}$seance$::jsonb),
  ('Étirements du soir', '10 minutes pour relâcher les tensions et mieux dormir.', 10, array['Tapis']::text[], 'Étirements', 'tous', $seance${"nom": "Étirements du soir", "jour": null, "duree": "10 min", "echauffement": null, "blocs": [{"titre": "Étirements", "format": "1 série", "exercices": [{"nom": "Étirement des ischios assise", "series": "1", "repetitions": "1 min", "charge": null, "repos": null, "tempo": null, "consignes": "Jambes tendues, tu te penches dos long, sans forcer."}, {"nom": "Fente basse (fléchisseurs de hanche)", "series": "1", "repetitions": "45 s / côté", "charge": null, "repos": null, "tempo": null, "consignes": "Bassin qui avance doucement, fessier serré."}, {"nom": "Étirement du fessier allongée (figure 4)", "series": "1", "repetitions": "45 s / côté", "charge": null, "repos": null, "tempo": null, "consignes": "Cheville sur le genou opposé, tu tires doucement."}, {"nom": "Torsion allongée", "series": "1", "repetitions": "45 s / côté", "charge": null, "repos": null, "tempo": null, "consignes": "Épaules au sol, tu laisses tomber les genoux sur le côté."}, {"nom": "Posture de l’enfant", "series": "1", "repetitions": "1 min", "charge": null, "repos": null, "tempo": null, "consignes": "Front au sol, bras devant, longues expirations."}, {"nom": "Respiration lente", "series": "1", "repetitions": "1 min", "charge": null, "repos": null, "tempo": null, "consignes": "Inspire 4 s, expire 6 s."}]}], "retour_au_calme": null, "notes": "Aucune douleur : tu vas juste jusqu’à la sensation d’étirement."}$seance$::jsonb),
  ('Mobilité hanches et dos', '10 minutes pour des hanches libres et un dos qui respire, parfait après une journée assise.', 10, array['Tapis']::text[], 'Mobilité', 'tous', $seance${"nom": "Mobilité hanches et dos", "jour": null, "duree": "10 min", "echauffement": null, "blocs": [{"titre": "Mobilité", "format": "2 tours", "exercices": [{"nom": "Chat-vache", "series": null, "repetitions": "45 s", "charge": null, "repos": null, "tempo": null, "consignes": "Tu enroules puis tu creuses le dos, vertèbre après vertèbre."}, {"nom": "Rotation thoracique à quatre pattes", "series": null, "repetitions": "30 s / côté", "charge": null, "repos": null, "tempo": null, "consignes": "Main derrière la tête, le coude va vers le plafond."}, {"nom": "Hip 90/90", "series": null, "repetitions": "45 s", "charge": null, "repos": null, "tempo": null, "consignes": "Assise, genoux à 90°, tu bascules d’un côté à l’autre sans les mains si possible."}, {"nom": "Fente avec rotation (étirement complet)", "series": null, "repetitions": "30 s / côté", "charge": null, "repos": null, "tempo": null, "consignes": "Grande fente, main au sol, l’autre bras s’ouvre vers le ciel."}, {"nom": "Squat profond tenu", "series": null, "repetitions": "45 s", "charge": null, "repos": null, "tempo": null, "consignes": "Talons au sol, coudes qui poussent les genoux vers l’extérieur. Tiens-toi à un meuble si besoin."}]}], "retour_au_calme": "Quelques respirations debout, bras au-dessus de la tête.", "notes": null}$seance$::jsonb),
  ('Corde à sauter express', '10 minutes de cardio vif avec ta corde : idéal en déplacement.', 10, array['Corde à sauter']::text[], 'Cardio', 'intermediaire', $seance${"nom": "Corde à sauter express", "jour": null, "duree": "10 min", "echauffement": "1 min de petits sauts sur place sans corde, puis rotations des poignets et des chevilles.", "blocs": [{"titre": "EMOM", "format": "EMOM 8 min", "exercices": [{"nom": "Corde à sauter (minutes impaires)", "series": null, "repetitions": "40 s", "charge": null, "repos": null, "tempo": null, "consignes": "Petits sauts sur l’avant du pied, coudes près du corps."}, {"nom": "Squat au poids du corps (minutes paires)", "series": null, "repetitions": "15", "charge": null, "repos": null, "tempo": null, "consignes": "Tu récupères le reste de la minute."}]}], "retour_au_calme": "1 min de marche puis étirement des mollets.", "notes": "Pas de corde ? Fais le même mouvement en mimant la corde."}$seance$::jsonb),
  ('Corps entier sans matériel', 'Le format « maison » : squats, pompes, fentes et gainage en circuit.', 15, '{}'::text[], 'Renfo', 'debutante', $seance${"nom": "Corps entier sans matériel", "jour": null, "duree": "15 min", "echauffement": "2 min : marche sur place, cercles de bras, 10 squats lents.", "blocs": [{"titre": "Circuit corps entier", "format": "3 tours – repos 1 min 30 entre les tours", "exercices": [{"nom": "Squat au poids du corps", "series": null, "repetitions": "15", "charge": null, "repos": "20 s", "tempo": null, "consignes": "Poitrine haute, genoux dans l’axe des pieds."}, {"nom": "Pompes sur les genoux", "series": null, "repetitions": "10", "charge": null, "repos": "20 s", "tempo": null, "consignes": "Corps gainé des genoux à la tête, la poitrine descend entre les mains."}, {"nom": "Fentes arrière", "series": null, "repetitions": "10 / jambe", "charge": null, "repos": "20 s", "tempo": null, "consignes": "Descends doucement, pousse dans le talon avant pour remonter."}, {"nom": "Planche sur les coudes", "series": null, "repetitions": "30 s", "charge": null, "repos": null, "tempo": null, "consignes": "Fessiers et ventre serrés."}]}], "retour_au_calme": "Étire tes cuisses et tes pectoraux, 30 s chacun.", "notes": "Trop facile ? Ralentis la descente (3 s) plutôt que d’aller plus vite."}$seance$::jsonb),
  ('Format 15 min : 3 mouvements', 'Tes 3 gros mouvements pour entretenir ta force : jambes, pousser, tirer.', 15, array['Haltères']::text[], 'Renfo', 'intermediaire', $seance${"nom": "Format 15 min : 3 mouvements", "jour": null, "duree": "15 min", "echauffement": "2 min de mobilité, puis une série légère de chaque exercice.", "blocs": [{"titre": "Force", "format": "3 séries", "exercices": [{"nom": "Goblet squat", "series": "3", "repetitions": "10-12", "charge": null, "repos": "60 s", "tempo": null, "consignes": "Haltère contre la poitrine, buste droit. Effort sérieux : il doit te rester 1 à 2 répétitions en réserve (RPE 8)."}, {"nom": "Développé militaire haltères", "series": "3", "repetitions": "10-12", "charge": null, "repos": "60 s", "tempo": null, "consignes": "Gainage du ventre, tu ne creuses pas le dos. Effort sérieux : il doit te rester 1 à 2 répétitions en réserve (RPE 8)."}, {"nom": "Rowing haltère un bras", "series": "3", "repetitions": "10-12 / bras", "charge": null, "repos": "60 s", "tempo": null, "consignes": "Dos plat, tu tires le coude vers la hanche. Effort sérieux : il doit te rester 1 à 2 répétitions en réserve (RPE 8)."}]}], "retour_au_calme": "1 min d’étirements du dos et des épaules.", "notes": "Qualité d’exécution avant la charge. Si tu es fatiguée aujourd’hui, respecte tes sensations plutôt que le chiffre : une séance plus légère reste une séance faite 💛"}$seance$::jsonb),
  ('Kettlebell EMOM', 'Une séance dynamique avec ta kettlebell : swing, squat, fentes, en EMOM.', 15, array['Kettlebell']::text[], 'Cardio', 'intermediaire', $seance${"nom": "Kettlebell EMOM", "jour": null, "duree": "15 min", "echauffement": "2 min : 10 bonjours (charnière de hanche) au poids du corps, 10 squats, 10 rotations de bras.", "blocs": [{"titre": "EMOM", "format": "EMOM 12 min", "exercices": [{"nom": "Kettlebell swing (minute 1)", "series": null, "repetitions": "15", "charge": null, "repos": null, "tempo": null, "consignes": "La force vient des hanches et des fessiers, pas des bras."}, {"nom": "Goblet squat (minute 2)", "series": null, "repetitions": "10", "charge": null, "repos": null, "tempo": null, "consignes": "Kettlebell contre la poitrine, descente contrôlée."}, {"nom": "Fentes arrière (minute 3)", "series": null, "repetitions": "10 (5 / jambe)", "charge": null, "repos": null, "tempo": null, "consignes": "Kettlebell en goblet ou sans charge."}]}], "retour_au_calme": "Étire tes fessiers et tes ischios, 1 min.", "notes": "Chaque minute, tu fais l’exercice puis tu récupères jusqu’à la minute suivante. 4 tours des 3 exercices."}$seance$::jsonb),
  ('Haut du corps à l’élastique', 'Dos, épaules et bras avec un simple élastique, parfait en déplacement.', 15, array['Élastique']::text[], 'Renfo', 'tous', $seance${"nom": "Haut du corps à l’élastique", "jour": null, "duree": "15 min", "echauffement": "1 min de cercles de bras, puis 10 tirages légers à l’élastique.", "blocs": [{"titre": "Haut du corps", "format": "3 tours – repos 1 min entre les tours", "exercices": [{"nom": "Rowing à l’élastique", "series": null, "repetitions": "15", "charge": null, "repos": "20 s", "tempo": null, "consignes": "Élastique accroché à une porte ou sous les pieds, tu serres les omoplates."}, {"nom": "Pompes sur les genoux", "series": null, "repetitions": "10", "charge": null, "repos": "20 s", "tempo": null, "consignes": "Ou pompes inclinées, mains sur un meuble stable."}, {"nom": "Face pull à l’élastique", "series": null, "repetitions": "15", "charge": null, "repos": "20 s", "tempo": null, "consignes": "Coudes hauts, tu tires vers le front."}, {"nom": "Développé épaules à l’élastique", "series": null, "repetitions": "12", "charge": null, "repos": null, "tempo": null, "consignes": "Élastique sous les pieds, gainage du ventre."}]}], "retour_au_calme": "Étire tes pectoraux contre un mur et l’arrière de tes épaules, 30 s chacun.", "notes": "Plus l’élastique est court, plus c’est difficile."}$seance$::jsonb),
  ('Format 20 min : 4 mouvements', 'Squat, charnière de hanche, pousser, tirer : ta séance complète en 20 minutes.', 20, array['Haltères']::text[], 'Renfo', 'intermediaire', $seance${"nom": "Format 20 min : 4 mouvements", "jour": null, "duree": "20 min", "echauffement": "3 min de mobilité générale, puis une série légère de goblet squat et de soulevé de terre.", "blocs": [{"titre": "Force", "format": "3 séries", "exercices": [{"nom": "Goblet squat", "series": "3", "repetitions": "10-12", "charge": null, "repos": "45 s", "tempo": null, "consignes": "Effort sérieux : il doit te rester 1 à 2 répétitions en réserve (RPE 8)."}, {"nom": "Soulevé de terre roumain haltères", "series": "3", "repetitions": "10-12", "charge": null, "repos": "45 s", "tempo": null, "consignes": "Dos plat, les haltères glissent le long des cuisses, tu sens l’étirement à l’arrière des jambes."}, {"nom": "Pompes", "series": "3", "repetitions": "8-12", "charge": null, "repos": "45 s", "tempo": null, "consignes": "Sur les genoux si besoin : la qualité avant tout."}, {"nom": "Rowing haltère un bras", "series": "3", "repetitions": "10-12 / bras", "charge": null, "repos": "45 s", "tempo": null, "consignes": "Effort sérieux : il doit te rester 1 à 2 répétitions en réserve (RPE 8)."}]}], "retour_au_calme": "2 min d’étirements : ischios, pectoraux, dos.", "notes": "Repos courts : tu enchaînes. Si tu es fatiguée aujourd’hui, respecte tes sensations plutôt que le chiffre : une séance plus légère reste une séance faite 💛"}$seance$::jsonb),
  ('Fessiers à la maison', 'Une séance fessiers complète avec un élastique : pont, fentes, abductions.', 20, array['Élastique', 'Tapis']::text[], 'Renfo', 'tous', $seance${"nom": "Fessiers à la maison", "jour": null, "duree": "20 min", "echauffement": "2 min : 15 ponts de fessiers sans élastique, 10 fentes arrière, cercles de hanches.", "blocs": [{"titre": "Fessiers", "format": "3 tours – repos 1 min entre les tours", "exercices": [{"nom": "Pont de fessiers à l’élastique", "series": null, "repetitions": "15", "charge": null, "repos": "30 s", "tempo": null, "consignes": "Élastique au-dessus des genoux, tu serres fort les fessiers 2 s en haut."}, {"nom": "Fentes arrière", "series": null, "repetitions": "12 / jambe", "charge": null, "repos": "30 s", "tempo": null, "consignes": "Buste légèrement penché vers l’avant pour plus de fessiers."}, {"nom": "Abductions allongée sur le côté", "series": null, "repetitions": "15 / jambe", "charge": null, "repos": "30 s", "tempo": null, "consignes": "Pied légèrement tourné vers le bas, mouvement lent."}, {"nom": "Pont de fessiers une jambe", "series": null, "repetitions": "10 / jambe", "charge": null, "repos": null, "tempo": null, "consignes": "Bassin bien droit, sans tourner."}]}], "retour_au_calme": "Étirement du fessier allongée (figure 4) et fente basse, 45 s par côté.", "notes": null}$seance$::jsonb),
  ('AMRAP haltères 12 min', 'Une séance intense et complète, au format que tu connais de la box.', 20, array['Haltères']::text[], 'Cardio', 'confirmee', $seance${"nom": "AMRAP haltères 12 min", "jour": null, "duree": "20 min", "echauffement": "4 min : 2 tours de 10 squats, 10 pompes faciles, 10 fentes, puis quelques push press légers.", "blocs": [{"titre": "Metcon", "format": "AMRAP 12 min", "exercices": [{"nom": "Push press haltères", "series": null, "repetitions": "10", "charge": null, "repos": null, "tempo": null, "consignes": "Petite flexion des jambes pour lancer les haltères au-dessus de la tête."}, {"nom": "Fentes arrière alternées haltères", "series": null, "repetitions": "12", "charge": null, "repos": null, "tempo": null, "consignes": "Haltères le long du corps, buste droit."}, {"nom": "Rowing haltères penchée", "series": null, "repetitions": "10", "charge": null, "repos": null, "tempo": null, "consignes": "Dos plat, tu tires les deux haltères vers le nombril."}, {"nom": "Burpees", "series": null, "repetitions": "6", "charge": null, "repos": null, "tempo": null, "consignes": "Version sans saut ni pompe si besoin."}]}], "retour_au_calme": "3 min de marche lente puis étirements des épaules et des cuisses.", "notes": "Le plus de tours possible en 12 min, en gardant une belle technique. Note ton score dans le commentaire pour te battre la prochaine fois !"}$seance$::jsonb),
